solution:
function coinChange(coins, amount) {
  const fewest = new Array(amount + 1).fill(Infinity);  // Infinity = "can't make it (yet)"
  fewest[0] = 0;
  for (let a = 1; a <= amount; a++) {
    for (const coin of coins) {
      if (coin <= a && fewest[a - coin] + 1 < fewest[a]) {
        fewest[a] = fewest[a - coin] + 1;   // use this coin last, on top of the best for a - coin
      }
    }
  }
  return fewest[amount] === Infinity ? -1 : fewest[amount];
}
